            Draft: T('Draft', '#6e7681', '#6e7781'), StateText: T('State Text', '#ffffff', '#ffffff'), BPill: T('Branch Pill', '#121d2f', '#ddf4ff'), BText: T('Branch Text', '#58a6ff', '#0969da'),
